import { useEffect, useMemo, useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { ipc } from "@/lib/ipc";

type License = { name: string; version: string; license: string; url: string; source: string };

/** Every third-party package in this build (generated by scripts/licenses.mjs), searchable. */
export function LicensesDialog({ open, onOpenChange }: { open: boolean; onOpenChange: (o: boolean) => void }) {
  const [all, setAll] = useState<License[] | null>(null);
  const [query, setQuery] = useState("");
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (open && !all) import("@/lib/licenses.json").then((m) => setAll(m.default as License[]));
  }, [open, all]);

  const shown = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!all) return [];
    return q ? all.filter((l) => l.name.toLowerCase().includes(q) || l.license.toLowerCase().includes(q)) : all;
  }, [all, query]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="flex max-h-[80vh] flex-col sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>Open-source licenses</DialogTitle>
          <DialogDescription>
            {all ? `${all.length} packages are part of Earshot.` : "Loading…"} The full license texts are in
            THIRD_PARTY_LICENSES.md next to the app.
          </DialogDescription>
        </DialogHeader>
        <div className="flex items-center gap-2">
          <Input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Filter by name or license"
            aria-label="Filter licenses"
            className="h-8"
          />
          <Button
            variant="outline"
            size="sm"
            onClick={() => ipc.revealLicenses().then(() => setError(null), (e) => setError(String(e)))}
          >
            Show license texts
          </Button>
        </div>
        {error && <p className="text-sm text-destructive">{error}</p>}
        <ul className="-mx-2 min-h-0 flex-1 overflow-y-auto px-2 text-sm" aria-label="Packages">
          {shown.map((l) => (
            <li key={`${l.source}:${l.name}@${l.version}`} className="flex items-center gap-2 border-b border-border/60 py-1.5">
              <span className="min-w-0 flex-1 truncate">
                {l.url ? (
                  <button
                    type="button"
                    onClick={() => ipc.openLink(l.url).catch(() => {})}
                    className="font-medium underline-offset-2 hover:underline"
                    title={l.url}
                  >
                    {l.name}
                  </button>
                ) : (
                  <span className="font-medium">{l.name}</span>
                )}
                <span className="ml-1.5 text-muted-foreground">{l.version}</span>
              </span>
              <span className="shrink-0 text-xs text-muted-foreground">{l.source}</span>
              <Badge variant="outline" className="block max-w-56 shrink-0 truncate font-normal" title={l.license}>
                {l.license}
              </Badge>
            </li>
          ))}
          {all && shown.length === 0 && <li className="py-6 text-center text-muted-foreground">No matches.</li>}
        </ul>
      </DialogContent>
    </Dialog>
  );
}
